PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS days (date TEXT PRIMARY KEY NOT NULL, type TEXT NOT NULL DEFAULT 'normal', study_budget_minutes INTEGER NOT NULL DEFAULT 150, exam_budget_minutes INTEGER NOT NULL DEFAULT 45);
CREATE TABLE IF NOT EXISTS decks (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, max_new_per_day INTEGER NOT NULL DEFAULT 5, weight INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY AUTOINCREMENT, deck_id INTEGER NOT NULL REFERENCES decks(id), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, url TEXT, difficulty TEXT, category TEXT, note TEXT, sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'new', stage INTEGER NOT NULL DEFAULT 0, due_date TEXT, lapses INTEGER NOT NULL DEFAULT 0, last_rating TEXT);
CREATE TABLE IF NOT EXISTS review_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, item_id INTEGER NOT NULL REFERENCES items(id), date TEXT NOT NULL, rating TEXT NOT NULL, before_json TEXT NOT NULL, minutes INTEGER, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, is_top3 INTEGER NOT NULL DEFAULT 0, est_minutes INTEGER, goal_id INTEGER REFERENCES goals(id), status TEXT NOT NULL DEFAULT 'open', drop_reason TEXT, carried_count INTEGER NOT NULL DEFAULT 0, recurring_id INTEGER, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS journals (date TEXT PRIMARY KEY NOT NULL, mood INTEGER, energy INTEGER, study_feel INTEGER, sleep_hours REAL, gains TEXT, problems TEXT, tomorrow_top1 TEXT);
CREATE TABLE IF NOT EXISTS exercises (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, body_part TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_templates (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, exercise_ids TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workouts (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, status TEXT NOT NULL, skip_reason TEXT, template_id INTEGER, duration_min INTEGER, feeling INTEGER, note TEXT);
CREATE TABLE IF NOT EXISTS workout_sets (id INTEGER PRIMARY KEY AUTOINCREMENT, workout_id INTEGER NOT NULL REFERENCES workouts(id), exercise_id INTEGER NOT NULL REFERENCES exercises(id), set_index INTEGER NOT NULL, weight_kg REAL NOT NULL, reps INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS body_weights (date TEXT PRIMARY KEY NOT NULL, kg REAL NOT NULL);
CREATE TABLE IF NOT EXISTS expense_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL, keywords TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, amount_cents INTEGER NOT NULL, kind TEXT NOT NULL, category_id INTEGER REFERENCES expense_categories(id), note TEXT);
CREATE TABLE IF NOT EXISTS note_category_memory (note TEXT PRIMARY KEY NOT NULL, category_id INTEGER NOT NULL REFERENCES expense_categories(id));
CREATE TABLE IF NOT EXISTS ai_reports (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, ref TEXT NOT NULL, model TEXT, input_hash TEXT NOT NULL, input TEXT NOT NULL, output TEXT, raw TEXT, status TEXT NOT NULL, tokens_in INTEGER, tokens_out INTEGER, latency_ms INTEGER);
CREATE TABLE IF NOT EXISTS __drizzle_migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS day_meta (date TEXT PRIMARY KEY NOT NULL, day_type TEXT NOT NULL DEFAULT 'normal', score INTEGER, score_detail TEXT);
CREATE TABLE IF NOT EXISTS daily_plans (date TEXT PRIMARY KEY NOT NULL, mode TEXT NOT NULL, budget_minutes INTEGER NOT NULL, backlog_count INTEGER NOT NULL, generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_plan_items (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL REFERENCES daily_plans(date), item_id INTEGER NOT NULL REFERENCES items(id), kind TEXT NOT NULL, position INTEGER NOT NULL, optional INTEGER NOT NULL DEFAULT 0, done_log_id INTEGER REFERENCES review_logs(id));
CREATE TABLE IF NOT EXISTS recurring_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, category TEXT NOT NULL, rule TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS goal_details (goal_id INTEGER PRIMARY KEY REFERENCES goals(id), deadline TEXT, description TEXT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS key_results (id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL REFERENCES goals(id), name TEXT NOT NULL, target_value REAL NOT NULL, current_value REAL NOT NULL DEFAULT 0, unit TEXT NOT NULL DEFAULT '', source TEXT);
CREATE TABLE IF NOT EXISTS meditation_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, duration_minutes INTEGER NOT NULL CHECK (duration_minutes BETWEEN 1 AND 120), started_at TEXT NOT NULL, completed_at TEXT);
